import{z as o,x as m,o as t,c as d,q as s,j as B,D as e,d as r,s as n,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Black–Scholes 作为 PDE","description":"","frontmatter":{"title":"Black–Scholes 作为 PDE","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bsm-as-pde.md","filePath":"quant/bsm-as-pde.md","lastUpdated":1791413859000}'),S={name:"quant/bsm-as-pde.md"};function c(h,a,A,p,D,_){const l=m("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="black–scholes-作为-pde" tabindex="-1">Black–Scholes 作为 PDE <a class="header-anchor" href="#black–scholes-作为-pde" aria-label="Permalink to &quot;Black–Scholes 作为 PDE&quot;">​</a></h1><div class="epigraph"><p>在 GBM 与常数利率下，欧式价格 $V(t,S)$ 满足 $V_t+\\tfrac12\\sigma^2 S^2 V_{SS}+r S V_S-r V=0$，终值是支付函数。</p><footer>—— 据 Black and Scholes, J. Political Economy, 1973；Merton, Bell Journal of Economics, 1973；Shreve, Stochastic Calculus for Finance II, 第 6 章整理</footer></div><p>上一课<a href="/quant/feynman-kac">Feynman–Kac</a>给出期望与 PDE 的桥。缺口是特化：标的为<a href="/quant/geometric-brownian-motion">几何布朗运动</a>，测度已是<a href="/quant/risk-neutral-measure">风险中性测度</a>下的 \\(Q\\)。把 \\(\\mu=rS\\)、\\(\\sigma_{\\text{diff}}=\\sigma S\\) 推进生成元，就得到 Black–Scholes 方程。本课只写这个 PDE 与终边值，不把闭式 \\(\\Phi(d_1)\\) 展开——那是对数正态课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(Q\\) 下 \\(\\mathrm d S=r S\\,\\mathrm d t+\\sigma S\\,\\mathrm d W^Q\\)。欧式支付 \\(H=g(S_T)\\)，价格 \\(V(t,S_t)=\\mathrm e^{-r(T-t)}\\mathbb E_Q[g(S_T)\\mid\\mathcal F_t]\\)。缺口是把 Feynman–Kac 的 \\(\\mathcal A\\) 写成具体系数，使后课 delta 对冲能对 \\(V_S\\) 说话。不重推 Girsanov，不重推 RN 存在性。</p><p>终值 \\(V(T,s)=g(s)\\)。看涨还要边界：\\(s\\to 0\\) 时 \\(V\\to 0\\)，\\(s\\to\\infty\\) 时 \\(V\\sim s-Ke^{-r(T-t)}\\)（在无股息时）。这些是 PDE 的数据，不是新的经济假设。</p><h3 id="pde-不是从投资组合瞬时无风险「另推一遍」再当定义" tabindex="-1">PDE 不是从投资组合瞬时无风险「另推一遍」再当定义 <a class="header-anchor" href="#pde-不是从投资组合瞬时无风险「另推一遍」再当定义" aria-label="Permalink to &quot;PDE 不是从投资组合瞬时无风险「另推一遍」再当定义&quot;">​</a></h3><p>Black–Scholes 原文用 \\(\\Delta\\) 对冲消去 \\(\\mathrm d W\\)，令收益率等于 \\(r\\)。那与「\\(Q\\) 下贴现鞅」是同一件事的两种语言。本课走 Feynman–Kac，是因为前面已经有 \\(Q\\)；不必把 1973 的推导再当第一性原理重做。复制课会回到 \\(\\Delta=V_S\\)。</p><p><span class="marginnote">无股息时漂移系数是 \\(rS\\)。连续股息 \\(q\\) 把 \\(rS\\) 换成 \\((r-q)S\\)，PDE 多一项 \\(-qSV_S\\)。本课先钉 \\(q=0\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2> \\[V_t+\\tfrac12\\sigma^2 S^2 V_{SS}+r S V_S-r V=0,\\qquad t\\lt T,\\ S\\gt 0, \\]<p>\\(V(T,S)=g(S)\\)。这是变系数抛物方程。对数坐标 \\(x=\\ln S\\) 把它变成常系数热方程，这是闭式与有限差分数值的共同入口。\\(\\sigma=0\\) 时退成贴现的运输方程，解为 \\(e^{-r(T-t)}g(Se^{r(T-t)})\\)，即远期兑现——与无风险情形一致。</p><p><span class="marginnote">「对数坐标化常系数」的直觉类比：变系数 PDE 像在坡度处处不同的山坡上走路，每一步都得重新问坡有多陡；取 \\(x=\\ln S\\) 相当于换成等高线地图，坡度处处一致，方程退化成大学传热学里的标准热方程，两百年的解法随便搬。</span></p><p>有股息、外汇、期货，只改生成元的一阶项（漂移），二阶项仍是 \\(\\tfrac12\\sigma^2 S^2 V_{SS}\\)。这与 Girsanov「不改波动率」一致。</p>',14)),(t(),B(i,null,{default:e(()=>[n(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20GBM%5B%22Q%20%E4%B8%8B%20GBM%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E5%85%83%22%5D%0A%20%20FK%5B%22Feynman-Kac%22%5D%20--%3E%20GEN%0A%20%20GEN%20--%3E%20PDE%5B%22Black-Scholes%20PDE%22%5D%0A%20%20PDE%20--%3E%20DELTA%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9AV%20%E5%AF%B9%20S%20%E7%9A%84%E5%81%8F%E5%AF%BC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"贴现过程 \\(\\mathrm e^{-rt}V(t,S_t)\\) 的 Itô 漂移由 PDE 恰好抵消，剩下 \\(\\mathrm e^{-rt}\\sigma S V_S\\,\\mathrm d W^Q\\)。因此贴现价格是 \\(Q\\)-局部鞅；在线性增长下是鞅，初值等于终端贴现支付的期望。PDE 的二阶项来自 \\([S]\\)，一阶项来自 \\(Q\\) 下的漂移 \\(rS\\)，零阶项来自贴现。缺任何一项都会让贴现价格带漂移，出现套利。",-1)),(t(),B(i,null,{default:e(()=>[n(l,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20I%5B%22It%C3%B4%20%E4%BF%AE%E6%AD%A3%E9%A1%B9%EF%BC%9AS%20%E7%9A%84%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%22%5D%20--%3E%20B%5B%22%E4%BA%8C%E9%98%B6%E9%A1%B9%20%C2%BD%CF%83%C2%B2S%C2%B2%C2%B7V_SS%22%5D%0A%20%20D%5B%22Q%20%E4%B8%8B%E6%BC%82%E7%A7%BB%20rS%22%5D%20--%3E%20A%5B%22%E4%B8%80%E9%98%B6%E9%A1%B9%20rS%C2%B7V_S%22%5D%0A%20%20P%5B%22%E8%B4%B4%E7%8E%B0%E5%9B%A0%E5%AD%90%20e%20%E7%9A%84%20%E2%88%92rt%20%E6%AC%A1%E5%B9%82%22%5D%20--%3E%20Z%5B%22%E9%9B%B6%E9%98%B6%E9%A1%B9%20%E2%88%92rV%22%5D%0A%20%20B%20--%3E%20M%5B%22%E4%B8%89%E9%A1%B9%E6%81%B0%E5%A5%BD%E6%8A%B5%E6%B6%88%20It%C3%B4%20%E6%BC%82%E7%A7%BB%EF%BC%9A%E8%B4%B4%E7%8E%B0%E4%BB%B7%E6%A0%BC%E6%98%AF%20Q-%E9%9E%85%22%5D%0A%20%20A%20--%3E%20M%0A%20%20Z%20--%3E%20M%0A%20%20M%20--%3E%20W%5B%22%E7%BC%BA%E4%BB%BB%E4%B8%80%E9%A1%B9%20%E2%86%92%20%E8%B4%B4%E7%8E%B0%E4%BB%B7%E6%A0%BC%E5%B8%A6%E6%BC%82%E7%A7%BB%20%E2%86%92%20%E5%A5%97%E5%88%A9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p>抛物性要求 \\(\\sigma\\neq 0\\)。\\(\\sigma=0\\) 是退化，解沿特征线，不再有平滑。数值上 \\(\\sigma\\) 过小要换格式，那是实现问题；理论上完备市场仍要求 \\(\\sigma\\neq 0\\) 以便 \\(\\theta\\) 有定义。</p><p><span class="marginnote">初学者容易以为 \\(\\sigma=0\\) 只是「波动小一点、算起来更简单」。实际上二阶项整体消失，方程从扩散退化成沿特征线运动的运输方程，解不再被平滑；期权价格就是「确定支付的贴现」，所有依赖扩散的数值格式在这一极限下集体失效。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解热方程，不引入隐含波动率曲面。美式把 PDE 换成变分不等式，跳把 PDE 换成 PIDE。后课默认：欧式扩散价格指这个柯西问题的多项式增长解。下一课<a href="/quant/replicating-delta">复制与 delta</a>把 \\(V_S\\) 读成股票持仓。</p><p><span class="marginnote">两个术语翻译：变分不等式就是「PDE 加一条不得低于内在价值的约束，贴着约束走还是解方程由市场说了算」；PIDE 是「偏微分—积分方程」，跳扩散让价格出现跳跃，积分项接管二阶项的活。改动支付与动态，方程家族随之换姓。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BSM PDE 是 \\(Q\\) 下 GBM 的 Feynman–Kac。</li><li>二阶项来自二次变差，一阶项来自风险中性漂移。</li><li>终值是支付；边界由无套利渐近给出。</li><li>与 1973 的瞬时无风险组合是同一条件。</li><li>出处：Black–Scholes 1973；Merton 1973；Shreve SDE II 第 6 章。</li></ul>',7))])}const f=o(S,[["render",c]]);export{P as __pageData,f as default};
